// Paperless-ngx: an emailed document has been filed. Posted by a Paperless workflow
// (Document Added + "email" tag) with webhook params {title, correspondent, id, url}.
// The link comes from Paperless itself, so no hostname lives in this flow.
var p=msg.payload||{};
if(typeof p==='string'){try{p=JSON.parse(p);}catch(e){p={};}}
var id=String(p.id||'').replace(/[^0-9]/g,'');
var title=String(p.title||'').trim().slice(0,150)||'(untitled)';
var corr=String(p.correspondent||'').trim();
if(!corr||corr==='none'||corr==='-none-')corr='No correspondent';
var out={cat:'Paperless',sub:corr,message:title,tag:'paperless_'+(id||Date.now())};
var url=String(p.url||'').trim();
if(/^https?:\/\/[^\s]+$/.test(url)&&url.indexOf('None/')===-1)out.url=url;
return out;

// Copy caller info into a plain object: the express req's ip getter does not survive
// the link to tab-ih, so the temp source logger there (ih-src-fn) would log '?'.
var r=msg.req||{};
msg.req={ip:r.ip,originalUrl:r.originalUrl||r.url,headers:{'user-agent':(r.headers&&r.headers['user-agent'])||''}};
delete msg.res;
return msg;
